from collections import Counter, deque
# use the test grid already in memory
# Replace each 4-connected singleton non-background component with the most frequent adjacent color.
def transform2(grid):
    h,w=len(grid),len(grid[0]); counts=Counter(v for row in grid for v in row); bg=counts.most_common(1)[0][0]
    out=[row[:] for row in grid]; seen=set()
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color==bg or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); cells=[]
        while q:
          y,x=q.popleft(); cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
              seen.add((yy,xx)); q.append((yy,xx))
        if len(cells)==1:
          y,x=cells[0]
          ns=[grid[yy][xx] for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)) if 0<=yy<h and 0<=xx<w]
          out[y][x]=Counter(ns).most_common(1)[0][0]
    return out
