def transform_bbox(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[row[:] for row in grid]; seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col==bg or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); cells=[]
        while q:
          y,x=q.popleft(); cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
              seen.add((yy,xx));q.append((yy,xx))
        comps.append((col,cells))
    boxes=[(col,min(y for y,x in cells),max(y for y,x in cells),min(x for y,x in cells),max(x for y,x in cells),cells) for col,cells in comps if len(cells)>1]
    for col,cells in comps:
      if len(cells)==1:
        y,x=cells[0]
        matches=[b for b in boxes if b[0]!=col and b[1]<=y<=b[2] and b[3]<=x<=b[4]]
        if matches:
          # choose the matching component whose actual cell is nearest, then larger component
          b=min(matches,key=lambda b:(min(abs(y-yy)+abs(x-xx) for yy,xx in b[5]),-len(b[5])))
          out[y][x]=b[0]
        else: out[y][x]=bg
    return out
